; bank 0x18 - zh-hack Game Over code + Chinese text streams
; Mapped at slot 0x6000 by the caller in bank 0 (Game Over routine).
; The slot 0x6000 is NOT touched by ZhDrawStub (it borrows 0x8000), so the
; stream bytes stay readable while the 12x12 glyph is drawn.
;   0x6000-0x603F : code (this file)
;   0x6040+       : Chinese streams, generated by tools/build_texts.py -> work/bank18.bin
; The original Japanese game over strings in bank 1 are left untouched.

ZGAMEOVER:      equ     0x6040      ; "game over" text (T011)
ZCONTINUE:      equ     0x604B      ; "continue" text (T012)

; === ZGameOverPrint: print game over + optional continue text ===
; Called with bank 0x18 already mapped at 0x6000.
ZGameOverPrint:
        LD      hl,ZGAMEOVER
        CALL    PrintTextXY
        LD      a,(0xc27f)
        AND     a
        RET     z
        LD      hl,ZCONTINUE
        JP      PrintTextXY

        DS      0x6040-$, 0xFF
        IFDEF   ZH_SHADOW
        INCBIN  "work/bank18.bin"
        ELSE
        DS      0x8000-$, 0xFF
        ENDIF
        ASSERT  $ == 0x8000
